type Breaker struct { failures, until int }
func (b *Breaker) Invoke(now int, request func() int) int {
    if now < b.until { return -1 }
    if request() == 1 { b.failures = 0; b.until = 0; return 1 }
    b.failures++
    if b.failures >= 2 { b.until = now + 5 }
    return 0
}

sealed class Breaker {
    int failures, until;
    public int Invoke(int now, System.Func<int> request) {
        if (now < until) return -1;
        if (request() == 1) { failures = 0; until = 0; return 1; }
        failures++;
        if (failures >= 2) until = now + 5;
        return 0;
    }
}

func Retry(request func() int, delay func(int)) int {
    pause := 1
    for attempt := 0; attempt < 3; attempt++ {
        status := request()
        if status != 503 { return status }
        if attempt < 2 { delay(pause); pause *= 2 }
    }
    return 503
}

static int Retry(System.Func<int> request, System.Action<int> delay) {
    int pause = 1;
    for (int attempt = 0; attempt < 3; attempt++) {
        int status = request();
        if (status != 503) return status;
        if (attempt < 2) { delay(pause); pause *= 2; }
    }
    return 503;
}

type Bulkhead chan struct{}
func NewBulkhead() Bulkhead { return make(chan struct{}, 1) }
func (b Bulkhead) Acquire() bool {
    select { case b <- struct{}{}: return true; default: return false }
}
func (b Bulkhead) Release() int { <-b; return 1 }
