func App(record int, sendLocal func(int)) { sendLocal(record) }
func Sidecar(in <-chan int, write func(int)) {
    for record := range in { write(record) }
}

static void App(int record, System.Action<int> sendLocal) => sendLocal(record);
static void Sidecar(System.Collections.Generic.IEnumerable<int> input,
                    System.Action<int> write) {
    foreach (int record in input) write(record);
}

func Ambassador(post func(string, string) int) int {
    const endpoint = "https://catalog.example"
    const route = "/catalog/read"
    status := post(endpoint, route)
    if status == 503 { return post(endpoint, route) }
    return status
}

static int Ambassador(System.Func<string,string,int> post) {
    const string endpoint = "https://catalog.example", route = "/catalog/read";
    int status = post(endpoint, route);
    return status == 503 ? post(endpoint, route) : status;
}

type Store interface { Read() int; Write(int) }
type Cache struct { store Store; ready bool; value int }
func (c *Cache) Get() int {
    if !c.ready { c.value = c.store.Read(); c.ready = true }
    return c.value
}
func (c *Cache) Put(v int) int { c.store.Write(v); c.ready = false; return v }

interface IStore { int Read(); void Write(int value); }
sealed class Cache(IStore store) {
    bool ready; int value;
    public int Get() {
        if (!ready) { value = store.Read(); ready = true; }
        return value;
    }
    public int Put(int v) { store.Write(v); ready = false; return v; }
}

type Throttle struct { window, count int }
func (t *Throttle) Allow(now int) bool {
    current := now / 10
    if current != t.window { t.window = current; t.count = 0 }
    if t.count >= 2 { return false }
    t.count++; return true
}

sealed class Throttle {
    int window = -1, count;
    public bool Allow(int now) {
        int current = now / 10;
        if (current != window) { window = current; count = 0; }
        if (count >= 2) return false;
        count++; return true;
    }
}

type Buffer struct { jobs []int }
func (b *Buffer) Accept(job int) { b.jobs = append(b.jobs, job) }
func (b *Buffer) Tick(process func(int)) {
    if len(b.jobs) == 0 { return }
    job := b.jobs[0]; b.jobs = b.jobs[1:]; process(job)
}

sealed class Buffer {
    readonly System.Collections.Generic.Queue<int> jobs = new();
    public void Accept(int job) => jobs.Enqueue(job);
    public void Tick(System.Action<int> process) {
        if (jobs.Count > 0) process(jobs.Dequeue());
    }
}

func Worker(jobs <-chan int, process func(int), done chan<- bool) {
    for job := range jobs { process(job) }
    done <- true
}
func Start(jobs <-chan int, process func(int)) {
    done := make(chan bool, 2)
    go Worker(jobs, process, done); go Worker(jobs, process, done)
    <-done; <-done
}

static async System.Threading.Tasks.Task Worker(
    System.Threading.Channels.ChannelReader<int> jobs,
    System.Action<int> process) {
    await foreach (int job in jobs.ReadAllAsync()) process(job);
}
static System.Threading.Tasks.Task Start(
    System.Threading.Channels.ChannelReader<int> jobs,
    System.Action<int> process) =>
    System.Threading.Tasks.Task.WhenAll(
        System.Threading.Tasks.Task.Run(() => Worker(jobs, process)),
        System.Threading.Tasks.Task.Run(() => Worker(jobs, process)));

